    using System;
using System.Collections.Generic;

class Graph
{
    private int V;
    private List<Tuple<int, int>>[] adj;

    public Graph(int V)
    {
        this.V = V;
        adj = new List<Tuple<int, int>>[V];
        for (int i = 0; i < V; ++i)
            adj[i] = new List<Tuple<int, int>>();
    }

    public void AddEdge(int u, int v, int w)
    {
        adj[u].Add(new Tuple<int, int>(v, w));
        adj[v].Add(new Tuple<int, int>(u, w));
    }

    public void PrimMST()
    {
        PriorityQueue<(int key, int vertex)> pq = new PriorityQueue<(int key, int vertex)>(Comparer<(int key, int vertex)>.Create((x, y) => x.key.CompareTo(y.key)));
        int src = 0;

        int[] key = new int[V];
        int[] parent = new int[V];
        bool[] inMST = new bool[V];

        for (int i = 0; i < V; ++i)
        {
            key[i] = int.MaxValue;
            parent[i] = -1;
            inMST[i] = false;
        }

        pq.Enqueue((0, src));
        key[src] = 0;

        while (pq.Count > 0)
        {
            int u = pq.Dequeue().vertex;

            if (inMST[u])
                continue;

            inMST[u] = true;

            foreach (var edge in adj[u])
            {
                int v = edge.Item1;
                int weight = edge.Item2;

                if (!inMST[v] && key[v] > weight)
                {
                    key[v] = weight;
                    pq.Enqueue((key[v], v));
                    parent[v] = u;
                }
            }
        }

        for (int i = 1; i < V; ++i)
        {
            Console.WriteLine($"{parent[i]} - {i}");
        }
    }
}

class PriorityQueue<T>
{
    private List<T> heap = new List<T>();
    private readonly Comparer<T> comparer;

    public int Count => heap.Count;

    public PriorityQueue(Comparer<T> comparer)
    {
        this.comparer = comparer;
    }

    // Added parameterless constructor
    public PriorityQueue() : this(Comparer<T>.Default) { }

    public void Enqueue(T item)
    {
        heap.Add(item);
        int i = heap.Count - 1;

        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (comparer.Compare(heap[parent], heap[i]) <= 0)
                break;

            Swap(parent, i);
            i = parent;
        }
    }

    public T Dequeue()
    {
        int count = heap.Count - 1;
        T front = heap[0];
        heap[0] = heap[count];
        heap.RemoveAt(count);

        count--;
        int i = 0;

        while (true)
        {
            int left = i * 2 + 1;
            int right = i * 2 + 2;

            if (left > count)
                break;

            int smallest = left;

            if (right <= count && comparer.Compare(heap[right], heap[left]) < 0)
                smallest = right;

            if (comparer.Compare(heap[i], heap[smallest]) <= 0)
                break;

            Swap(i, smallest);
            i = smallest;
        }

        return front;
    }

    private void Swap(int i, int j)
    {
        T temp = heap[i];
        heap[i] = heap[j];
        heap[j] = temp;
    }
}

